class BattlePreviewControllerV4 extends ChangeNotifier{BattlePreviewControllerV4({required this.encounter,required int seed,DungeonCarryStateV4? carry,int hpPotions=2}):hpPotions=hpPotions,engine=const EncounterLoaderV4().buildEngine(encounter,seed:seed,carry:carry){selectedTarget=encounter.enemies.isEmpty?const HexCoord(4,3):encounter.enemies.first.anchor;engine.beginNextActivation();_advanceEnemyTurns();}final EncounterDefinitionV4 encounter;final CombatEngineV4 engine;final HeadlessPolicyV4 policy=const HeadlessPolicyV4();bool auto=false;int speed=1;int hpPotions;HexCoord selectedTarget=const HexCoord(4,3);V4ActionCategory selectedCategory=V4ActionCategory.attack;V4InteractionMode interactionMode=V4InteractionMode.command;String? selectedSkillId;static const _assetsByName={'Wizard':'assets/art/wizard/body_back.webp','Goblin Scout':'assets/art/enemy/goblin_scout.webp','Elder Slime':'assets/art/boss/elder_slime.webp'};bool get isBattleOver=>engine.battleOver;bool get didWin=>engine.winner==CombatTeamV4.party;int get boardColumns=>encounter.columns;int get boardRows=>encounter.rows;Map<HexCoord,TerrainV4> get terrain=>encounter.terrain;List<CombatUnitV4> get partyCombatUnits=>engine.units.where((u)=>u.team==CombatTeamV4.party).toList(growable:false);Set<HexCoord> get telegraphHexes{final runtime=engine.runtime[BoneHeapBehaviorV4.runtimeKey];return runtime is BoneHeapRuntimeV4?Set.of(runtime.pendingSweepHexes):const{};}List<V4BattleUnit> get units=>[for(final unit in engine.units)V4BattleUnit(id:unit.id,name:unit.name,team:unit.team==CombatTeamV4.party?V4Team.party:V4Team.enemy,anchor:unit.anchor,maxHp:unit.stats.maxHp,hp:unit.hp,maxMp:unit.stats.maxMp,mp:unit.mp,speed:unit.stats.speed,size:switch(unit.size){UnitSizeV4.normal=>V4UnitSize.normal,UnitSizeV4.large3=>V4UnitSize.large3,UnitSizeV4.huge7=>V4UnitSize.huge7},assetPath:_assetsByName[unit.name],footprint:unit.occupiedHexes.toList(growable:false),statuses:_statusBadges(unit),barrier:unit.barrierTotal,isPlaceholder:!_assetsByName.containsKey(unit.name))];CombatUnitV4? get activeCombatUnit=>engine.activeUnit??engine.timelinePreview(limit:1).firstOrNull;V4BattleUnit get activeUnit{final a=activeCombatUnit;return a==null?units.first:units.firstWhere((u)=>u.id==a.id);}List<String> get timeline=>engine.timelinePreview(limit:8).map((u)=>u.id).toList();V4BattleUnit? get boss{final b=units.where((u)=>u.team==V4Team.enemy&&u.size!=V4UnitSize.normal);return b.isEmpty?null:b.first;}void toggleAuto(){auto=!auto;if(auto)_runAutoWindow();notifyListeners();}void setSpeed(int v){if(v<1||v>3)return;speed=v;notifyListeners();}void selectTarget(HexCoord t){selectedTarget=t;notifyListeners();}void selectUnit(String id){final t=engine.units.where((u)=>u.id==id).firstOrNull;if(t!=null){selectedTarget=t.anchor;notifyListeners();}}void _advanceEnemyTurns(){var g=0;while(!engine.battleOver&&g++<24){var a=engine.activeUnit;a??=engine.beginNextActivation();if(a==null||!engine.activationOpen)return;if(a.team==CombatTeamV4.party)return;policy.takeActivation(engine);}_resetCommandUi();}void _runAutoWindow(){var g=0;while(auto&&!engine.battleOver&&g++<400){var a=engine.activeUnit;a??=engine.beginNextActivation();if(a==null||!engine.activationOpen)continue;policy.takeActivation(engine);}_resetCommandUi();}CombatUnitV4? targetAt(HexCoord c){for(final u in engine.units){if(!u.isKo&&u.occupiedHexes.contains(c))return u;}return null;}void _resetCommandUi(){interactionMode=V4InteractionMode.command;selectedSkillId=null;}}
List<V4StatusBadge> _statusBadges(CombatUnitV4 unit){final r=<V4StatusBadge>[];for(final s in unit.statuses){final d=switch(s.type){StatusTypeV4.stunned=>('ST','Stunned',100),StatusTypeV4.rooted=>('RT','Rooted',90),StatusTypeV4.poisoned=>('PO','Poisoned',80),StatusTypeV4.burning=>('BU','Burning',75),StatusTypeV4.bleeding=>('BL','Bleeding',70),StatusTypeV4.disrupted=>('DI','Disrupted',65),StatusTypeV4.exposed=>('EX','Exposed',60),StatusTypeV4.slowed=>('SL','Slowed',50),StatusTypeV4.weakened=>('WK','Weakened',45),StatusTypeV4.guarded=>('GU','Guarded',35),StatusTypeV4.haste=>('HA','Haste',30),StatusTypeV4.marked=>('MK','Marked',20)};r.add(V4StatusBadge(code:d.$1,label:d.$2,priority:d.$3,stacks:s.stacks));}r.sort((a,b)=>b.priority.compareTo(a.priority));return r;}extension _FirstOrNull<T> on Iterable<T>{T? get firstOrNull=>isEmpty?null:first;}
